<div wire:poll.5s="checkExpiry" x-data="{remaining:Math.max(0,{{ (int) floor(now()->diffInSeconds($attempt->expires_at, false)) }}),confirmSubmit:false}" x-init="setInterval(()=>{if(remaining>0)remaining--;if(remaining===0)$wire.checkExpiry()},1000)" class="space-y-5"><header class="sticky top-16 z-30 rounded-2xl border border-slate-200 bg-white/95 p-4 shadow-card"><div class="flex flex-wrap items-center justify-between gap-4"><div><p class="text-xs font-semibold uppercase tracking-wider text-slate-400">Tiến độ bài thi</p><p class="mt-1 font-bold text-slate-900">Câu {{ $currentIndex+1 }} / {{ $questions->count() }}</p></div><div class="rounded-xl px-5 py-2.5 text-center ring-1 ring-inset" :class="remaining<60?'bg-red-100 text-red-700 ring-red-200':remaining<300?'bg-amber-100 text-amber-800 ring-amber-200':'bg-primary-50 text-primary-700 ring-primary-100'"><span class="block text-[10px] font-bold uppercase tracking-wider">Thời gian còn lại</span><span class="font-mono text-2xl font-bold tabular-nums" x-text="String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0')"></span></div></div></header><div class="grid items-start gap-6 lg:grid-cols-[1fr_300px]"><x-card class="min-h-[480px]"><div class="mb-6 flex items-center justify-between"><x-badge variant="blue">{{ $question?->type==='multiple'?'Chọn nhiều đáp án':'Chọn một đáp án' }}</x-badge>@if($flagged[$question?->id]??false)<x-badge variant="yellow">⚑ Đã đánh dấu</x-badge>@endif</div>@if($question)<h2 class="text-lg font-bold leading-8 text-slate-950 sm:text-xl">{{ $question->content }}</h2><div class="mt-7 space-y-3">@foreach($question->options as $option)@php($active=in_array($option->id,$selected,true))<button type="button" wire:click="selectOption({{ $option->id }})" class="group flex w-full items-center gap-4 rounded-2xl border-2 p-4 text-left transition focus-visible:ring-2 focus-visible:ring-primary-500 {{ $active?'border-primary-500 bg-primary-50 text-primary-950 shadow-sm':'border-slate-200 bg-white text-slate-700 hover:border-primary-300 hover:bg-primary-50/40' }}"><span class="grid h-8 w-8 shrink-0 place-items-center {{ $question->type==='single'?'rounded-full':'rounded-lg' }} border-2 text-sm font-bold {{ $active?'border-primary-600 bg-primary-600 text-white':'border-slate-300 bg-white' }}">{{ $active?'✓':chr(65+$loop->index) }}</span><span class="font-medium leading-6">{{ $option->content }}</span></button>@endforeach</div>@endif<div class="mt-9 flex flex-wrap items-center justify-between gap-3 border-t border-slate-100 pt-6"><x-button type="button" variant="secondary" wire:click="toggleFlag">{{ $flagged[$question?->id]??false?'Bỏ đánh dấu':'⚑ Đánh dấu xem lại' }}</x-button><div class="flex gap-2"><x-button type="button" variant="secondary" wire:click="previous" :disabled="$currentIndex===0">← Trước</x-button><x-button type="button" wire:click="next" :disabled="$currentIndex >= $questions->count()-1">Tiếp →</x-button></div></div></x-card><aside class="lg:sticky lg:top-44"><x-card title="Danh sách câu hỏi"><div class="grid grid-cols-5 gap-2">@foreach($questions as $index=>$item)<button type="button" wire:click="goTo({{ $index }})" aria-label="Đến câu {{ $index+1 }}" class="relative h-11 rounded-xl border text-sm font-bold transition {{ $index===$currentIndex?'border-primary-700 bg-primary-700 text-white ring-2 ring-primary-200':(in_array($item->id,$answeredIds,true)?'border-emerald-300 bg-emerald-50 text-emerald-700':'border-slate-300 bg-white text-slate-600 hover:border-primary-300') }}">{{ $index+1 }}@if($flagged[$item->id]??false)<span class="absolute -right-1 -top-1 h-3 w-3 rounded-full bg-amber-400 ring-2 ring-white"></span>@endif</button>@endforeach</div><div class="mt-5 space-y-2 text-xs text-slate-500"><p><span class="mr-2 inline-block h-3 w-3 rounded bg-primary-600"></span>Đang xem</p><p><span class="mr-2 inline-block h-3 w-3 rounded bg-emerald-100 ring-1 ring-emerald-300"></span>Đã trả lời</p><p><span class="mr-2 inline-block h-3 w-3 rounded-full bg-amber-400"></span>Đánh dấu xem lại</p></div><button type="button" @click="confirmSubmit=true" class="mt-6 w-full rounded-xl bg-emerald-600 px-4 py-3 font-bold text-white shadow-sm hover:bg-emerald-700">Nộp bài</button></x-card></aside></div><div x-cloak x-show="confirmSubmit" x-transition class="fixed inset-0 z-50 grid place-items-center bg-slate-500/30 p-4" role="dialog" aria-modal="true"><div @click.outside="confirmSubmit=false" class="w-full max-w-md rounded-2xl bg-white p-6 shadow-2xl"><div class="grid h-12 w-12 place-items-center rounded-full bg-amber-100 text-2xl">!</div><h2 class="mt-4 text-xl font-bold text-slate-950">Xác nhận nộp bài</h2><p class="mt-3 leading-6 text-slate-600">Bạn còn <strong class="text-slate-900">{{ $unansweredCount }} câu chưa trả lời</strong>. Sau khi nộp, bạn không thể sửa đáp án.</p><div class="mt-6 flex justify-end gap-3"><x-button type="button" variant="secondary" @click="confirmSubmit=false">Tiếp tục làm</x-button><x-button type="button" wire:click="submit">Xác nhận nộp</x-button></div></div></div></div>
